# PowerShell installer for the hardened TORQ source bundle
$ErrorActionPreference = "Stop"
$b64 = ""
[System.IO.File]::WriteAllBytes("torq_bundle.zip", [System.Convert]::FromBase64String($b64))
Expand-Archive -Path "torq_bundle.zip" -DestinationPath "." -Force
Remove-Item -Path "torq_bundle.zip" -ErrorAction SilentlyContinue
Write-Host "Hardened TORQ source bundle extracted successfully." -ForegroundColor Green
